// Defensive parse of LLM batch output.
// W2 (round W): the previous version blindly emitted whatever the model
// returned then let Mark items drafted mark ALL claimed ids as drafted —
// creating a bug where items without a corresponding draft row silently
// flipped to 'drafted'. This version:
//   1) validates cardinality (log-level warn only, we still want partial drafts),
//   2) deduplicates on idx (LLM sometimes repeats — keep first),
//   3) skips rows where body is empty (LLM returned idx but no content).
// Items without an emitted draft stay in 'batch_rewriting' with locked_at set
// (see Mark items drafted's EXISTS gate and WF07 watchdog branch B).
const rows = $('Pack batch').first().json.rows;
const parsed = JSON.parse($json.choices?.[0]?.message?.content || '{"results":[]}');
const rawResults = Array.isArray(parsed.results) ? parsed.results : [];

if (rawResults.length !== rows.length) {
  console.warn(`[WF08] LLM cardinality mismatch: batch=${rows.length}, returned=${rawResults.length}. Missing items will stay batch_rewriting (picked up by WF07 stuck watchdog after 30m).`);
}

const seenIdx = new Set();
const out = [];
for (const r of rawResults) {
  const idx = Number(r.idx);
  if (!Number.isInteger(idx) || idx < 1 || idx > rows.length) continue;
  if (seenIdx.has(idx)) continue;
  seenIdx.add(idx);
  const item = rows[idx - 1];
  const fb = r.facebook || {};
  const body = (fb.body || '').trim();
  if (!body) continue;
  out.push({ json: {
    itemId: item.id,
    orgId:  $env.ZALOCRM_ORG_ID,
    platform: 'facebook',
    variantKey: 'batch-v1',
    body,
    hashtags: Array.isArray(fb.hashtags) ? fb.hashtags : [],
    status: 'pending_review',
    scheduledAt: new Date(Date.now() + 2 * 3600 * 1000).toISOString()
  } });
}
return out;
